import{_ as p,o as t,c as a,a4 as _}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"给育种装上“智慧大脑”——北京以数智引领种业未来","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"给育种装上“智慧大脑”——北京以数智引领种业未来","date":"2026-09-04T00:00:00.000Z","source":"中国农业信息网","category":"news","link":"https://www.agri.cn/xxh/zhny/202609/t20260904_8869247.htm","summary":"田野里，无人车沿玉米行前行，机器一边“看”，算法一边“算”；鸡舍里，种鸡的产蛋、体重等数据不断汇入系统，基因芯片与算法共同寻找更有潜力的个体；实验室里，育种人员用自然语言提出目标，人工智能开始检索资料、调用模型、生成方案。\\n这些正在北京发生的新场景，勾勒出同一个方向：育种正在从主要依靠经验，走向数据与经验结合、人脑与机器协同。\\n9月4日至5日，第三十三届中国北京种业大会将在北京举行。...\\n","contentHash":"d7e7c5b5184115fbbf0b69b1dd71c1bf","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-09-04-给育种装上-智慧大脑-北京以数智引领种业未来.md","filePath":"news/2026-09-04-给育种装上-智慧大脑-北京以数智引领种业未来.md"}'),r={name:"news/2026-09-04-给育种装上-智慧大脑-北京以数智引领种业未来.md"};function n(s,e,o,i,d,l){return t(),a("div",null,[...e[0]||(e[0]=[_('<h1 id="给育种装上-智慧大脑-——北京以数智引领种业未来" tabindex="-1">给育种装上“智慧大脑”——北京以数智引领种业未来 <a class="header-anchor" href="#给育种装上-智慧大脑-——北京以数智引领种业未来" aria-label="Permalink to &quot;给育种装上“智慧大脑”——北京以数智引领种业未来&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.agri.cn/xxh/zhny/202609/t20260904_8869247.htm" target="_blank" rel="noreferrer">中国农业信息网</a><br> 日期: 2026-09-04 摘要: 田野里，无人车沿玉米行前行，机器一边“看”，算法一边“算”；鸡舍里，种鸡的产蛋、体重等数据不断汇入系统，基因芯片与算法共同寻找更有潜力的个体；实验室里，育种人员用自然语言提出目标，人工智能开始检索资料、调用模型、生成方案。 这些正在北京发生的新场景，勾勒出同一个方向：育种正在从主要依靠经验，走向数据与经验结合、人脑与机器协同。 9月4日至5日，第三十三届中国北京种业大会将在北京举行。...</p></blockquote><p>田野里，无人车沿玉米行前行，机器一边“看”，算法一边“算”；鸡舍里，种鸡的产蛋、体重等数据不断汇入系统，基因芯片与算法共同寻找更有潜力的个体；实验室里，育种人员用自然语言提出目标，人工智能开始检索资料、调用模型、生成方案。</p><p>这些正在北京发生的新场景，勾勒出同一个方向：育种正在从主要依靠经验，走向数据与经验结合、人脑与机器协同。</p><p>9月4日至5日，第三十三届中国北京种业大会将在北京举行。大会以“AI赋能智慧育种·数智引领种业未来”为主题，首次以智慧育种为主线。人工智能怎样进入田间、鸡舍和实验室？它究竟改变了育种的哪一步？答案藏在正在采集的数据、实际的选种过程和不断落地的技术中。</p><p>机器“看”玉米</p><p>在北京通州区于家务乡的通州国际种业科技园区基地，20亩试验田里的约7万株玉米，正在接受一场“全周期体检”。环绕式无人车拍下植株的颜色、纹理和株型，激光雷达勾勒三维结构，多光谱和热成像设备捕捉长势与温度变化。一台不足半米宽的机器人则钻入冠层之下，从另一个视角补上从上方看不到的信息，近距离记录茎秆粗细、植株疏密和吐丝进度。</p><p>从6叶期到9叶期，再到大喇叭口期和吐丝期，设备目前已完成4个阶段的数据采集，后续还将跟踪至成熟期。一次作业由两人操作，每小时可完成约4000株的数据采集。1000株以内的小批量数据，4至6小时可以形成结果，全区域数据可在24小时内完成解析和质控。在海南崖州南繁基地，同类装备还与无人机协同作业，在240亩试验田完成了超过36万株玉米的全生育期数据采集。</p><p>交到育种人员手中的，不只是田间照片，还有性状数据表、三维点云模型、品系对比图表和单株表型档案。阶段性数据已能初步区分不同品系的株高增长速度、叶夹角和冠层透光性差异。团队随机抽取100株玉米，以人工测量的株高作对照，机器测量结果的一致性超过95%，误差低于5厘米。</p><p>“过去依靠人工作业和经验判断，现在通过机器标准化采集、算法自动化处理，获取的指标更多、维度更多，精度也更高。”北京市农林科学院信息技术研究中心研究员郭新宇介绍，表型是基因型与环境互作的结果，只有把表型数据与基因组数据结合起来，才能更好地认识不同基因型在真实田间究竟会有怎样的表现。</p><p>表型大数据工厂所做的，就是把作物真实的“长相”和“长势”变成AI可以学习的语言，帮助育种人员判断哪些材料在耐密、抗倒伏和高产方面更具潜力。</p><p>算法“评”种鸡</p><p>一只尚未产蛋的雏鸡，能不能提前判断它将来产多少蛋、蛋重多大、蛋壳结不结实？在北京市华都峪口禽业有限责任公司，一管血可以帮助育种人员更早读出候选种鸡的遗传潜力。</p><p>研发人员闫奕源把选种比作选学生：传统方法要等母鸡产蛋，取得产蛋数、蛋重、蛋品质等“考试成绩”后才能判断。有了基因数据和预测模型，则可以在候选种鸡尚无自身生产记录时，提前评价其遗传潜能。</p><p>雏鸡出生后采集血液、提取DNA，再用蛋鸡育种芯片检测基因变异位点。亲本和群体的历史数据中，既有基因型，也有产蛋数、蛋重、体重、蛋壳颜色和强度等表型数据。模型从两类数据的对应关系中学习，再对新一批候选种鸡逐只预测，形成涵盖不同性状的“成绩单”和综合排名。</p><p>在这套体系中，芯片负责检测基因变异，算法模型则接过大规模比较、遗传潜能预测和排序等工作，帮助育种人员更早看出哪些个体更有育种潜力。“选得准，才能更快实现育种目标。”闫奕源说。</p><p>目前，“京粉6号”已在百万只规模养殖条件下稳定实现“700天产500枚蛋”，相关成果获得2025年度国家科学技术进步奖二等奖。接续这一成熟品种，本届大会将发布“京红2号”“京粉8号”“沃德178”“京翠绿壳”等自主研发蛋（肉）鸡新品种，呈现“京字号”种鸡持续迭代的新成果。</p><p>平台“串”流程</p><p>如果说田间表型工厂解决的是“数据从哪里来”，种鸡精准育种展示的是“算法怎样辅助选择”，那么即将在本届大会发布的“神农育种Studio”，要解决的是分散的数据、模型和软件怎样被育种人员更方便地用起来。</p><p>过去，育种人员常常需要在数据库、表格和多种软件间反复切换，有些环节还要请信息技术人员编写程序。现在，育种人员用自然语言提出目标，Studio先识别任务所需的数据、模型和软件，再按需调用相应工具，完成资料检索、亲本筛选、品系评价、多环境试验分析等任务。各环节自动衔接，前一步的结果成为下一步的输入，最后汇成附有资料来源的报告。</p><p>支撑平台运行的，是团队多年积累的农业知识、生产数据和育种模型。神农大模型的数据底座已汇集超过1000万条农业知识图谱数据、超过5000万条农业生产数据。在北京市怀柔区，团队借助平台从数百个生菜品种中海选出“雁栖1号”“雁栖2号”。中国农业大学副教授王耀君介绍，过去一个蔬菜新品种往往要五六年才能培育出来，借助海量数据分析，可将时间缩短至两三年。</p><p>9月4日，“神农育种Studio”将正式发布。Studio把原本分散的研究环节自动串联起来，效率变化随之显现。以设计一套小麦育种方案为例，王耀君介绍，过去需要投入10人月——即1个人工作10个月，或10个人工作1个月；在育种人员把目标和逻辑梳理清楚后，借助Studio可降至0.5人月。资料检索、数据处理、模型计算和初步方案生成等原本分散的工作，可由平台连续完成。</p><p>从机器进田采数据，到算法辅助选材料，再到大模型串起研究环节，3种场景勾勒出智能育种的一条数据链路，也对算力、数据、装备和公共服务提出新要求。</p><p>北京市农业农村局有关负责人介绍，北京将依托农业中关村核心区，打造北京农业中关村智能育种创新基地，计划建设智能育种共性技术创新中心和智能育种共性装备创新中心，提升育种专用算力、数据治理、装备研发中试、基因检测、标准规范和成果转化等共性条件；面向作物、畜禽、水产、微生物打造四类智能育种测试平台与产业应用场景。目前，作物逆境表型鉴定平台、作物智能分子育种创新平台、畜禽智能育种技术共性平台等重大平台正在建设中。</p><p>育种仍是一场以年为单位的长跑，人工智能不能让种子跳过生长季，却能接过大量重复、耗时的前期工作。它可以把田间观察变成更完整的数据，把海量候选材料排出次序，把分散的研究环节自动串联起来，让每一轮选择少花一些时间、少走一些弯路。当机器真正读懂田间，数据、算法与育种经验形成合力，一粒好种子走向生产的脚步，便能迈得更快、更稳。（农民日报全媒体记者 芦晓春 赵天浩）</p><p><a href="https://www.agri.cn/xxh/zhny/202609/t20260904_8869247.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',26)])])}const h=p(r,[["render",n]]);export{f as __pageData,h as default};
